import json,re
from pathlib import Path
S=Path('/tmp/opensip-design-corrections/incoming-binding-successor.v1/source/docs')
# product-configuration analysis.capabilities shape
for p in S.rglob('*.json'):
    if '/reviews/' in str(p): continue
    t=p.read_text(errors='replace')
    if '\"capabilities\"' in t and 'product-configuration' in p.name:
        d=json.loads(t)
        def walk(n,trail):
            if isinstance(n,dict):
                if 'capabilities' in (n.get('properties') or {}):
                    print(p.relative_to(S),'/'.join(trail),'->',json.dumps(n['properties']['capabilities'])[:700])
                for k,v in n.items(): walk(v,trail+[str(k)])
            elif isinstance(n,list):
                for i,v in enumerate(n): walk(v,trail+[str(i)])
        walk(d,[])
E=(S/'coop/design-corrections/foundation/enumeration_model.v1.py').read_text().splitlines()
for i,l in enumerate(E):
    if re.search(r'raise .*(ENUMERATION_[A-Z_]*(TUPLE|TOTAL|MISSING|CELL|MEMBERSHIP|UNIT|COVER)[A-Z_]*)', l): print('enum',i+1,'|',l.strip()[:170])
